document.getElementById('year').textContent=new Date().getFullYear();document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});document.getElementById('filter-status').textContent='Showing '+button.textContent.toLowerCase();document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter&&card.dataset.category!=='all';});}));
